def _real_mro(cls: type) -> Tuple[type, ...]:
    """``cls`` 的**真实** MRO（``tp_mro``），不经元类 ``__getattribute__``。"""
    return cls.__mro__


def _class_namespace(klass: type) -> Any:
    """``klass`` 的**真实**类命名空间（``tp_dict`` 的 mappingproxy），不经元类钩子。"""
    return vars(klass)
